'use strict';
let reports=[],checklist=[],reportQuery='';
Object.assign(labels,{categories:'品类规划',competitors:'竞对档案',reports:'研究资料库'});
types.historical='历史原始报价';types.wholesale_reference='公开批发参考';scope='all';
const originalGroup=group,originalDetail=showRecord,originalStore=store;
group=function(o){if(['round5','round6'].includes(o.origin))return o.category_group||'待分类';if(o.origin!=='legacy')return originalGroup(o);const c=o.category; if(/冰品|冰淇淋|雪糕/.test(c))return '冰品';if(/乳|奶/.test(c))return '乳品';return ({6:'乳品',7:'冰品',8:'酒类',9:'个护纸品',10:'香烟',13:'水饮咖啡',14:'方便速食',15:'促销跨品类',20:'鲜食原料',21:'鲜食原料',23:'水饮咖啡',24:'零食',25:'方便速食',26:'酒类',27:'个护纸品',28:'乳品'})[o.task_id]||c};
const reportLink=(id,label)=>'<button class="report-link" data-report="'+id+'">'+escapeHtml(label||('报告 '+String(id).padStart(2,'0')))+' ↗</button>';
const keyOf=o=>o.task_id+':'+o.id;
const countScope=s=>records.filter(o=>s==='legacy'?o.origin==='legacy':s==='round6'?o.origin==='round6':s==='round5'?o.origin==='round5':s==='reviewed'?o.origin!=='legacy'&&o.origin!=='round5'&&o.origin!=='round6':o.candidate_for_comparison).length;
function metric(value,label,note){return '<div class="metric"><span>'+label+'</span><strong>'+value+'</strong><small>'+note+'</small></div>'}
function coverage(){return [...new Set(records.map(group))].map(c=>({name:c,all:records.filter(o=>group(o)===c).length,old:records.filter(o=>group(o)===c&&o.origin==='legacy').length,candidates:records.filter(o=>group(o)===c&&o.candidate_for_comparison).length})).sort((a,b)=>b.all-a.all)}
function coverageTable(limit){return '<div class="table-wrap"><table class="coverage-table"><thead><tr><th>品类</th><th>资料记录</th><th>历史记录</th><th>复核候选</th><th>研究入口</th></tr></thead><tbody>'+coverage().slice(0,limit).map(c=>'<tr><td><strong>'+c.name+'</strong></td><td>'+c.all+'</td><td>'+c.old+'</td><td>'+c.candidates+'</td><td><button class="report-link" data-category="'+c.name+'">查看明细 ↗</button></td></tr>').join('')+'</tbody></table></div>'}
function priceCells(o){if(o.origin==='legacy'){const p=o.raw_prices;return '<strong>'+escapeHtml(p['批发价低']||'—')+' – '+escapeHtml(p['批发价高']||'—')+'</strong><small>批发原值 · 单位待核</small>'}return '<strong>'+(o.normalized_price!=null?fmt(o.normalized_price)+(o.normalized_price_high!=null?'–'+fmt(o.normalized_price_high):''):'—')+'</strong><small>'+escapeHtml(o.normalized_unit||'未获得价格')+'</small>'}
function productTable(rows){return '<div class="table-wrap"><table class="records-table"><thead><tr><th>商品 / 规格</th><th>品类</th><th>价格 / 批发参考</th><th>零售 / 促销原值</th><th>供应商 / 来源</th><th>日期 / 口径</th><th>资料状态</th></tr></thead><tbody>'+rows.map(o=>'<tr data-key="'+escapeHtml(keyOf(o))+'" tabindex="0" class="product-row"><td><strong>'+escapeHtml(o.sku)+'</strong><small>'+escapeHtml(o.spec)+'</small></td><td>'+group(o)+'</td><td>'+priceCells(o)+'</td><td>'+(o.origin==='legacy'?escapeHtml(o.raw_prices['零售价']||'—')+' / '+escapeHtml(o.raw_prices['促销低价']||'—')+'<small>单位与条件待核</small>':'<span class="chip">'+(types[o.price_type]||'资料')+'</span>')+'</td><td class="source-cell">'+escapeHtml(o.supplier||o.source_title)+'</td><td>'+escapeHtml(o.source_date||'来源未标日期')+'<small>引 '+o.task_id+' 号</small></td><td><span class="chip '+(o.candidate_for_comparison?'warm':'')+'">'+(o.origin==='legacy'?'历史 · 待核单位':o.candidate_for_comparison?'可比候选':'研究线索')+'</span></td></tr>').join('')+'</tbody></table></div>'}
overview=function(){main.innerHTML=intro('经营研究总览','商品、价格、品类、竞争与供应链的统一研究入口。','EVERY MART / RESEARCH WORKSPACE')+'<div class="metrics">'+metric(records.length,'累计研究记录','含重复商品与多源观察')+metric(reports.length,'完整研究报告','基础盘 · 深入采集 · 决策方案')+metric(countScope('legacy'),'历史价格记录','原始报价保留，单位待核')+metric(countScope('round5'),'第五轮证据观察','同品供货 · 规格 · 历史与竞对')+metric(countScope('candidate'),'可比候选记录','仍需核实到店交易条件')+metric(400,'单店商品位置','试点配置建议，非在售数')+'</div><div class="workspace-grid"><section class="panel"><div class="panel-head"><h2>品类研究覆盖</h2><a href="#categories">全部品类 ↗</a></div>'+coverageTable(10)+'<p class="panel-note">记录数代表研究覆盖，不能用于判断销量、市场规模或品类热度。</p></section><section class="panel decision-rail"><div class="panel-head"><h2>集团决策台</h2><span class="chip">待验证</span></div>'+[['01','选品结构','400 位配额：试点先留 20 位鲜食，日配成熟后扩至 50 位。',32],['02','采购基准','先核箱规、起订、运费和有效期，再形成到店价。',75],['03','竞争定位','同商圈比标品与早餐组合，连锁规模口径分开看。',73],['04','门店验证','50 项同规格巡店清单，配合四周试点执行。',33]].map(x=>'<article class="decision"><span>'+x[0]+'</span><div><h3>'+x[1]+'</h3><p>'+x[2]+'</p>'+reportLink(x[3],'阅读依据')+'</div></article>').join('')+'</section></div><section class="panel"><div class="panel-head"><h2>批发核价线索</h2><a href="#products">进入 '+records.length+' 条商品与证据记录 ↗</a></div>'+productTable(records.filter(o=>o.candidate_for_comparison&&o.price_type==='wholesale').slice(0,6))+'</section><div class="bottom-grid"><section class="panel"><div class="panel-head"><h2>关键研究文件</h2><a href="#reports">全部 '+reports.length+' 份 ↗</a></div>'+[115,114,113,32,75,72].map(id=>'<div class="index-row"><span class="small">'+id+'</span>'+reportLink(id,reports.find(r=>r.id===id)?.title)+'</div>').join('')+'</section><section class="panel"><div class="panel-head"><h2>下一步补齐的数据</h2><span class="small">责任建议</span></div>'+[['竞对实售价与条码','区域运营 / 店长'],['有效到店报价与退换条件','采购'],['动销、缺货与报损记录','试点店长'],['POS 授权与月度复盘','集团运营']].map(x=>'<div class="index-row"><strong>'+x[0]+'</strong><span class="small">'+x[1]+'</span></div>').join('')+'</section></div>'};
products=function(){main.innerHTML=intro('商品与价格研究','完整接入各轮记录；点击任一行追溯原始报价、交易条件与报告。','PRODUCT DATABASE')+'<div class="notice">历史原值可能混用箱、件、瓶、条等单位，不能跨列直接算毛利；“可比候选”也不代表已取得现行到店报价。</div><div class="toolbar"><input id="search" class="search" type="search" aria-label="搜索商品" placeholder="搜索商品、条码、规格、供应商" value="'+escapeHtml(query)+'"><select id="category" aria-label="品类"><option value="all">全部品类</option>'+coverage().map(c=>'<option '+(category===c.name?'selected':'')+'>'+c.name+'</option>').join('')+'</select><select id="scope" aria-label="记录范围">'+[['all','全部研究 · '+records.length],['round6','持续采集 · '+countScope('round6')],['round5','第五轮证据 · '+countScope('round5')],['reviewed','第四轮证据 · '+countScope('reviewed')],['legacy','历史价格 · '+countScope('legacy')],['candidate','可比候选 · '+countScope('candidate')]].map(x=>'<option value="'+x[0]+'" '+(scope===x[0]?'selected':'')+'>'+x[1]+'</option>').join('')+'</select><select id="price-type" aria-label="价格性质"><option value="all">全部价格性质</option>'+Object.entries(types).map(([k,v])=>'<option value="'+k+'" '+(priceType===k?'selected':'')+'>'+v+'</option>').join('')+'</select></div><div id="results"></div>';renderResults();document.querySelector('#search').oninput=e=>{query=e.target.value;page=1;renderResults()};for(const [id,set]of [['category',v=>category=v],['scope',v=>scope=v],['price-type',v=>priceType=v]])document.getElementById(id).onchange=e=>{set(e.target.value);page=1;renderResults()}};
filtered=function(){return records.filter(o=>(scope==='all'||scope==='legacy'&&o.origin==='legacy'||scope==='reviewed'&&o.origin!=='legacy'&&o.origin!=='round5'&&o.origin!=='round6'||scope==='round6'&&o.origin==='round6'||scope==='round5'&&o.origin==='round5'||scope==='candidate'&&o.candidate_for_comparison)&&(category==='all'||group(o)===category)&&(priceType==='all'||priceType===o.price_type)&&[o.sku,o.spec,o.supplier,o.source_title,o.barcode].join(' ').toLowerCase().includes(query.trim().toLowerCase()))};
renderResults=function(){const rows=filtered(),pages=Math.max(1,Math.ceil(rows.length/25));page=Math.min(page,pages);document.getElementById('results').innerHTML='<div class="section-head"><strong>'+rows.length+' 条匹配记录</strong><span class="small">每页 25 条 · 点击行查看依据</span></div>'+productTable(rows.slice((page-1)*25,page*25))+(!rows.length?'<div class="empty">未找到匹配记录，请调整筛选。</div>':'')+'<div class="pager"><button class="btn" id="clear">重置筛选</button><div class="pager-buttons"><button class="btn" id="prev" '+(page===1?'disabled':'')+'>上一页</button><span>'+page+' / '+pages+'</span><button class="btn" id="next" '+(page===pages?'disabled':'')+'>下一页</button></div></div>';document.getElementById('prev').onclick=()=>{page--;renderResults()};document.getElementById('next').onclick=()=>{page++;renderResults()};document.getElementById('clear').onclick=()=>{query='';scope=category=priceType='all';page=1;databaseView()}};
showRecord=function(key){const o=records.find(x=>keyOf(x)===key);if(o?.origin!=='legacy')return originalDetail(key);showDialog('历史记录 / 引 '+o.task_id+' 号','<span class="chip">历史价格 · 单位待核</span><h2>'+escapeHtml(o.sku)+'</h2><p>'+escapeHtml(o.spec)+'</p><div class="notice">以下按旧 CSV 原值保留。批发、零售和促销可能使用不同单位，未自动折算，也不能直接计算毛利。</div><dl>'+Object.entries(o.raw_prices).concat([['来源原文',o.supplier],['原记录日期',o.source_date],['生效口径','记录日期不等于报价有效期；需重新确认']]).map(([k,v])=>'<dt>'+escapeHtml(k)+'</dt><dd>'+escapeHtml(v||'未获得')+'</dd>').join('')+'</dl>'+reportLink(o.task_id,'阅读完整来源报告'))};
function categories(){main.innerHTML=intro('品类规划与覆盖','对照研究储备和 400 位配额，明确下一步选品与补证顺序。','CATEGORY PLANNING')+'<div class="workspace-grid"><section class="panel"><div class="panel-head"><h2>全品类资料矩阵</h2><span class="small">点击查看商品</span></div>'+coverageTable()+'</section>'+allocation()+'</div><section class="panel"><div class="panel-head"><h2>毛利评估口径</h2>'+reportLink(32,'方案与假设')+'</div><div class="formula">商品毛利率 =（同单位售价 − 到店成本）÷ 同单位售价</div><p>到店成本须包含运费及不可抵扣费用；鲜食还需记录出品损耗和未售报损。目前没有门店实际销量与成本，暂不展示“实际毛利排名”。</p><div class="index-row">采购核到店价 → 店长记录售价与损耗 → 集团结合动销决定配置</div></section>'}
const competitorsData=[['7‑11','鲜食、便当与早餐组合','比较份量、组合价与出品时段','成都公开菜单可作线索，有效期仍需核实',[16,22,56]],['罗森','饭团、甜品与本地供应链','比较新品频率、陈列与组合','川渝门店口径不能直接作为成都门店数',[17,73]],['全家','咖啡、面包与即食组合','比较早餐价格带及复购商品','历史档案中的外地活动不能套用成都',[17,22]],['红旗连锁','社区覆盖与烟酒民生品','比较同商圈常购标品及便利服务','公司整体毛利、收入结构不等于单店或单品',[18,73]],['舞东风','社区型便利场景','比较到店距离、价格及商品重合','1095 家为所引榜单年度口径，非当前成都实时数',[19,73]]];
function competitors(){main.innerHTML=intro('竞对研究档案','将品牌策略、区域口径与门店实采分开，形成可执行的竞争观察。','COMPETITIVE INTELLIGENCE')+'<section class="panel"><div class="panel-head"><h2>五大竞对比较</h2><a href="#store">同商圈实采清单 ↗</a></div><div class="table-wrap"><table><thead><tr><th>品牌</th><th>研究关注点</th><th>集刻需要比较</th><th>口径边界</th><th>完整档案</th></tr></thead><tbody>'+competitorsData.map(x=>'<tr><td><strong>'+x[0]+'</strong></td><td>'+x[1]+'</td><td>'+x[2]+'</td><td>'+x[3]+'</td><td>'+x[4].map(id=>reportLink(id)).join(' ')+'</td></tr>').join('')+'</tbody></table></div></section><section class="panel"><div class="panel-head"><h2>竞争与扩张证据</h2><span class="small">公开资料快照 · 非实时监控</span></div>'+productTable(records.filter(o=>o.task_kind==='competitor'||o.task_id===73))+'</section><div class="notice">红旗自身股份转让与“收购舞东风”是不同事项。现有研究未取得后者正式公告；不能把媒体意向写成已完成并购。</div>'}
suppliers=function(){const rows=records.filter(o=>o.task_id===72||o.task_id===56&&o.price_type==='nonprice'||o.task_kind==='fresh');main.innerHTML=intro('供应渠道与采购线索','从品类供货、鲜食工厂到冷链配送，逐项核实覆盖区域及交易条件。','SUPPLY NETWORK')+'<div class="notice">公开线索不等于有效供货承诺。询价需同时确认箱规、起订、运费、保质期、退换责任与报价有效期。</div><section class="panel"><div class="panel-head"><h2>供应与服务资料</h2>'+reportLink(72,'完整渠道研究')+'</div>'+productTable(rows)+'</section><div class="supplier-grid">'+supply.map(x=>'<article class="panel"><span class="chip">'+x[0]+'</span><h2>'+x[1]+'</h2><p>'+x[2]+'</p><div class="conditions">需核：'+x[3]+'</div><a href="'+x[4]+'" target="_blank" rel="noopener noreferrer">公开来源 ↗</a></article>').join('')+'</div><section class="panel"><div class="panel-head"><h2>渠道专题档案</h2></div>'+[4,11,20,21,29,30,53,54,55,56,72,74].map(id=>'<div class="index-row">'+reportLink(id,reports.find(r=>r.id===id)?.title)+'</div>').join('')+'</section>'};
store=function(){originalStore();main.insertAdjacentHTML('beforeend','<section class="panel"><div class="panel-head"><h2>50 项巡店商品清单</h2><a href="store-price-check.csv" download>下载 CSV ↓</a></div><div class="table-wrap"><table><thead><tr><th>序号</th><th>品类</th><th>商品</th><th>规格</th><th>执行状态</th></tr></thead><tbody>'+checklist.map((r,i)=>'<tr><td>'+String(i+1).padStart(2,'0')+'</td><td>'+escapeHtml(r['品类'])+'</td><td><strong>'+escapeHtml(r.SKU)+'</strong></td><td>'+escapeHtml(r['规格'])+'</td><td><span class="chip">待实采</span></td></tr>').join('')+'</tbody></table></div></section>')};
function reportLibrary(){main.innerHTML=intro('研究资料库','完整收录 '+reports.length+' 份报告，支持标题与正文检索；每份报告均可阅读及下载。','RESEARCH LIBRARY')+'<div class="notice">历史报告保留研究过程，部分口径已被后续核验修订。决策优先参考 32、34、75、113–115 号及最新复核证据；原报告中的估计值不能当作实测。</div><div class="toolbar"><input class="search" id="report-search" type="search" placeholder="搜索标题或全文，例如：起订、烤肠、无糖茶" aria-label="搜索报告" value="'+escapeHtml(reportQuery)+'"></div><div id="report-results"></div>';renderReports();document.getElementById('report-search').oninput=e=>{reportQuery=e.target.value;renderReports()}}
function renderReports(){const rs=reports.filter(r=>(r.title+r.body).toLowerCase().includes(reportQuery.toLowerCase().trim()));document.getElementById('report-results').innerHTML='<div class="section-head"><strong>'+rs.length+' 份报告</strong><span class="small">点击打开全文</span></div><div class="table-wrap"><table><thead><tr><th>编号</th><th>研究专题</th><th>研究阶段</th><th>内容规模</th><th>原文</th></tr></thead><tbody>'+rs.map(r=>'<tr><td>'+String(r.id).padStart(2,'0')+'</td><td>'+reportLink(r.id,r.title)+'</td><td>'+r.phase+'</td><td>'+r.body.length.toLocaleString()+' 字符</td><td><a href="reports/'+String(r.id).padStart(2,'0')+'.md" download>下载 ↓</a></td></tr>').join('')+'</tbody></table></div>'}
function inlineMD(s){return escapeHtml(s).replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,(_,t,u)=>'<a href="'+escapeHtml(safeUrl(u.replace(/&amp;/g,'&')))+'" target="_blank" rel="noopener noreferrer">'+t+'</a>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>')}
function markdown(body){let table=false,code=false,out=[];for(const line of body.split('\n')){if(line.startsWith('```')){if(table){out.push('</tbody></table></div>');table=false}code=!code;out.push(code?'<pre>':'</pre>');continue}if(code){out.push(escapeHtml(line)+'\n');continue}if(/^\s*\|/.test(line)){if(!table){out.push('<div class="table-wrap"><table><tbody>');table=true}if(!/^\s*\|[\s:|\-]+\|\s*$/.test(line))out.push('<tr>'+line.trim().replace(/^\||\|$/g,'').split('|').map(c=>'<td>'+inlineMD(c.trim())+'</td>').join('')+'</tr>');continue}if(table){out.push('</tbody></table></div>');table=false}const h=line.match(/^(#{1,6})\s+(.+)/);out.push(h?'<h'+Math.min(h[1].length+1,6)+'>'+inlineMD(h[2])+'</h'+Math.min(h[1].length+1,6)+'>':line.trim()?'<p>'+inlineMD(line)+'</p>':'')}if(table)out.push('</tbody></table></div>');if(code)out.push('</pre>');return out.join('')}
function openReport(id){const r=reports.find(r=>r.id===Number(id));if(!r)return;showDialog('完整报告 / '+String(id).padStart(2,'0'),'<div class="report-document"><div class="notice">研究档案 · 部分为历史报价或估计。决策口径请结合 34、75、113–115 号核验结论。</div><a class="btn" href="reports/'+String(id).padStart(2,'0')+'.md" download>下载原文 ↓</a>'+markdown(r.body)+'</div>')}
route=function(){let id=location.hash.slice(1)||'overview';if(!labels[id])id='overview';document.getElementById('breadcrumb').textContent=labels[id];document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===id);a.setAttribute('aria-current',a.dataset.nav===id?'page':'false')});({overview,products,categories,competitors,suppliers,store,reports:reportLibrary}[id])()};
document.addEventListener('click',e=>{const r=e.target.closest('[data-report]');if(r)openReport(r.dataset.report);const c=e.target.closest('[data-category]');if(c){category=c.dataset.category;scope=priceType='all';query='';page=1;location.hash='database';route()}});
document.getElementById('about').onclick=()=>showDialog('数据与使用说明','<h2>研究资产与使用口径</h2><p>已接入 '+records.length+' 条研究记录：历史价格 '+countScope('legacy')+' 条、第四轮 '+countScope('reviewed')+' 条、第五轮 '+countScope('round5')+' 条、持续采集 '+countScope('round6')+' 条。同一商品可重复出现，记录数不等于独立 SKU 数。</p><p>'+reports.length+' 份完整报告与 50 项待执行采价清单均可查阅。可比候选仍需核实交易条件；第五轮保留重复记录标记及原始来源，不把格式校验当作真实性认证。</p><p>历史原始报价单位可能不同，不自动算毛利。未接入 POS、实时库存或真实动销。400 位配额与四周试点为方案建议。</p>'+reportLink(115,'本轮核验与缺口'));
const detailBeforeRound5=showRecord;
const exactText=s=>String(s||'').toLowerCase().replace(/\s+/g,'').replace(/[×＊]/g,'x');
function relatedEvidence(o){return records.filter(x=>keyOf(x)!==keyOf(o)&&x.origin!=='legacy'&&((o.barcode_format_valid&&x.barcode_format_valid&&o.barcode===x.barcode&&exactText(o.spec)===exactText(x.spec))||(exactText(o.sku)===exactText(x.sku)&&exactText(o.spec)===exactText(x.spec))))}
showRecord=function(key){const o=records.find(x=>keyOf(x)===key);if(!o)return;detailBeforeRound5(key);if(o.origin==='legacy')return;const related=relatedEvidence(o);document.getElementById('dialog-body').insertAdjacentHTML('beforeend','<section class="evidence-extra"><h3>商品规格与研究关联</h3><dl>'+[['来源明示条码',o.barcode?(o.barcode+' · '+(o.barcode_format_valid?'格式校验通过，仍需核包装':'待核')):'未获得'],['品牌 / 厂商',[o.brand,o.manufacturer].filter(Boolean).join(' / ')||'未获得'],['保质期',o.shelf_life||'未获得'],['储存要求',o.storage||'未获得'],['采集轮次',o.origin==='round6'?'持续采集 / 第六轮':o.origin==='round5'?'第五轮':'第四轮'],['重复证据关联',o.duplicate_of||'未标记；不代表已完成全量语义去重']].map(([k,v])=>'<dt>'+k+'</dt><dd>'+escapeHtml(v)+'</dd>').join('')+'</dl>'+reportLink(o.task_id,'阅读该专题完整报告')+'<h3>同品规其他来源 / 历史记录 · '+related.length+' 条</h3><p class="small">按校验通过的条码或完全一致的名称与规格关联；不同日期、渠道、供应商和促销条件不能直接比较。无匹配不等于没有其他货源。</p>'+(related.length?productTable(related):'<p>本库暂无可直接关联的其他观察。可返回商品库，搜索同名商品检查不同包装或命名。</p>')+'</section>')};

let competitorView='store',competitorQuery='',competitorPage=1;
competitors=function(){const items=records.filter(o=>o.task_kind==='competitor'||o.task_id===73);main.innerHTML=intro('竞对档案与巡店线索','按门店地址安排实采；结合公开菜单和经营披露比较商品与服务。','COMPETITIVE INTELLIGENCE')+'<section class="panel"><div class="panel-head"><h2>五大竞对比较</h2><a href="#store">下载实采清单 ↗</a></div><div class="table-wrap"><table><thead><tr><th>品牌</th><th>研究关注点</th><th>集刻需要比较</th><th>口径边界</th><th>完整档案</th></tr></thead><tbody>'+competitorsData.map(x=>'<tr><td><strong>'+x[0]+'</strong></td><td>'+x[1]+'</td><td>'+x[2]+'</td><td>'+x[3]+'</td><td>'+x[4].map(id=>reportLink(id)).join(' ')+'</td></tr>').join('')+'</tbody></table></div></section><section class="panel"><div class="panel-head"><div class="switch">'+[['store','门店地址'],['menu','公开菜单'],['event','经营与事件']].map(([k,t])=>'<button data-competitor-view="'+k+'" class="'+(competitorView===k?'active':'')+'">'+t+' · '+items.filter(o=>(o.record_kind||'event')===k).length+'</button>').join('')+'</div><span class="small">目录与历史快照 · 非实时</span></div><div class="toolbar"><input id="competitor-search" class="search" type="search" aria-label="搜索竞对资料" placeholder="搜索品牌、门店、道路、商圈或商品" value="'+escapeHtml(competitorQuery)+'"></div><div id="competitor-results"></div></section><div class="notice">菜单有效日期与门店营业状态需实采确认。舞东风的榜单与报道店数口径不同；见福交易的补充公告不等于已完成交割或翻牌。'+reportLink(108,'查看最新核验')+'</div>';renderCompetitors();document.getElementById('competitor-search').oninput=e=>{competitorQuery=e.target.value;competitorPage=1;renderCompetitors()}};
function renderCompetitors(){let rows=records.filter(o=>(o.task_kind==='competitor'||o.task_id===73)&&(o.record_kind||'event')===competitorView&&[o.sku,o.spec,o.brand,o.evidence].join(' ').toLowerCase().includes(competitorQuery.trim().toLowerCase()));const pages=Math.max(1,Math.ceil(rows.length/20));competitorPage=Math.min(competitorPage,pages);const current=rows.slice((competitorPage-1)*20,competitorPage*20);document.getElementById('competitor-results').innerHTML='<div class="section-head"><strong>'+rows.length+' 条匹配资料</strong><span class="small">点击行查看来源及条件</span></div>'+(competitorView==='menu'?productTable(current):'<div class="table-wrap"><table><thead><tr><th>品牌 / '+(competitorView==='store'?'门店':'事项')+'</th><th>'+(competitorView==='store'?'公开地址':'披露内容')+'</th><th>来源 / 日期</th><th>使用边界</th></tr></thead><tbody>'+current.map(o=>'<tr class="product-row" tabindex="0" data-key="'+escapeHtml(keyOf(o))+'"><td><strong>'+escapeHtml(o.sku)+'</strong></td><td>'+escapeHtml(o.spec)+'</td><td>'+escapeHtml(o.supplier||o.source_title)+'<small>'+escapeHtml(o.source_date||'来源未标日期')+'</small></td><td class="source-cell">'+escapeHtml(o.conditions||'具体适用范围待核')+'</td></tr>').join('')+'</tbody></table></div>')+(!rows.length?'<p class="empty">暂无匹配资料，请调整搜索词。</p>':'')+'<div class="pager"><span class="small">每页 20 条</span><div class="pager-buttons"><button id="competitor-prev" class="btn" '+(competitorPage===1?'disabled':'')+'>上一页</button><span>'+competitorPage+' / '+pages+'</span><button id="competitor-next" class="btn" '+(competitorPage===pages?'disabled':'')+'>下一页</button></div></div>';document.getElementById('competitor-prev').onclick=()=>{competitorPage--;renderCompetitors()};document.getElementById('competitor-next').onclick=()=>{competitorPage++;renderCompetitors()}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-competitor-view]');if(b){competitorView=b.dataset.competitorView;competitorPage=1;competitors()}});

let essentialsReady=false,libraryReady=false,essentialsError=false,libraryError=false,essentialsRequest=null,libraryRequest=null;
async function fetchJSON(path){const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),15000);try{const response=await fetch(path,{cache:'no-cache',signal:controller.signal});if(!response.ok)throw Error(path);return await response.json()}finally{clearTimeout(timeout)}}
function renderLoadState(title,error,kind){main.innerHTML='<section class="tool-panel load-state" role="status"><span class="eyebrow">EVERY MART</span><h1>'+escapeHtml(error?'这部分资料暂未载入':title)+'</h1><p>'+(error?'网络可能暂时不可用。已保存的本设备记录仍保留，重试后可以继续。':'请稍候。')+'</p>'+(error?'<button class="btn primary" data-retry-load="'+kind+'">重试载入</button>':'')+(kind==='library'?'<a class="btn" href="#overview">返回经营简报</a>':'')+'</section>'}
function loadEssentials(){if(essentialsRequest)return essentialsRequest;essentialsError=false;essentialsRequest=Promise.all(['incremental.json','checklist.json','reports-incremental.json'].map(fetchJSON)).then(([incremental,list,docs])=>{records=incremental;checklist=list;reports=docs;essentialsReady=true;route()}).catch(()=>{essentialsError=true;route()}).finally(()=>{essentialsRequest=null});return essentialsRequest}
function ensureLibrary(){if(!essentialsReady)return loadEssentials().then(()=>{if(!essentialsReady)throw Error('essentials');return ensureLibrary()});if(libraryReady)return Promise.resolve();if(libraryRequest)return libraryRequest;libraryError=false;libraryRequest=Promise.all(['data.json','legacy.json','reports.json','round5.json'].map(fetchJSON)).then(([current,old,docs,newRound])=>{records=[...records.filter(r=>r.origin==='round6'),...newRound,...current,...old];reports=[...docs,...reports.filter(r=>Number(r.id)>115)];libraryReady=true;if(['reports','database','categories','competitors','suppliers'].includes(location.hash.slice(1)))route()}).catch(error=>{libraryError=true;if(['reports','database','categories','competitors','suppliers'].includes(location.hash.slice(1)))renderLoadState('完整研究资料',true,'library');else intelligenceNotice('研究资料暂未载入，可稍后重试；当前工具仍可用');throw error}).finally(()=>{libraryRequest=null});return libraryRequest}
const openLoadedReport=openReport;
openReport=async function(id){if(!reports.some(r=>r.id===Number(id))){try{await ensureLibrary()}catch{return}}openLoadedReport(id)};
const aboutLoaded=document.getElementById('about').onclick;
document.getElementById('about').onclick=async()=>{try{await ensureLibrary();aboutLoaded()}catch{}};
document.addEventListener('click',e=>{const button=e.target.closest('[data-retry-load]');if(!button)return;if(button.dataset.retryLoad==='library'){renderLoadState('正在打开完整研究资料',false,'library');ensureLibrary().catch(()=>{})}else{renderLoadState('正在准备经营简报与行动工具',false,'essentials');loadEssentials()}});
loadEssentials();
